import com.rabbitmq.client.Channel;
import com.rabbitmq.client.Connection;
import com.rabbitmq.client.ConnectionFactory;

public class RabbitMQTopologyConfig {
    public static void main(String[] args) throws Exception {
        ConnectionFactory factory = new ConnectionFactory();
        factory.setHost("localhost");

        try (Connection connection = factory.newConnection();
             Channel channel = connection.createChannel()) {

            String exchangeName = "order.events";
            String queueName = "order.email.processor";
            String routingKey = "order.created.#";

            // Declare a Topic Exchange (durable=true, autoDelete=false)
            channel.exchangeDeclare(exchangeName, "topic", true);

            // Declare a durable Queue
            channel.queueDeclare(queueName, true, false, false, null);

            // Bind the queue to the exchange using a routing pattern
            channel.queueBind(queueName, exchangeName, routingKey);

            String message = "{ \"orderId\": 10023, \"status\": \"CREATED\" }";
            channel.basicPublish(exchangeName, "order.created.us-east", null, message.getBytes());
            System.out.println(" [x] Sent message to exchange with routing key.");
        }
    }
}
